SELECT COUNT(1) FROM test_paper
AND paper_type = #{paperType}
AND ( company LIKE CONCAT('%', #{keyword}, '%') OR paper_name LIKE CONCAT('%', #{keyword}, '%') )

SELECT paper_id as paperId, paper_name as paperName, company, paper_type as paperType, question_count as questionCount, create_time as createTime, update_time as updateTime FROM test_paper
AND paper_type = #{paperType}
AND ( company LIKE CONCAT('%', #{keyword}, '%') OR paper_name LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY create_time DESC LIMIT #{pageSize} OFFSET #{offset}
